// Shared V5 controlled-provider test budget. No retries or refunds after uncertain I/O.
export const AI_TEST_LIMITS = Object.freeze({
  // Per model call, not catalog capacity. Navigation avoids whole-tree prompts.
  // Text budget doubled after adding paged tool results; output remains bounded.
  llmRequestBytes: 262144,
  llmMaxOutputTokens: 8192,
  llmReservationMicrousd: 250000,
  speechPcmBytes: 3840000,
  speechMaxOutputTokens: 8192,
  speechReservationMicrousd: 200000,
  speechCaptureMs: 120000,
  speechFinalizationMs: 15000,
});

export type AiTestBudgetResult = {
  admitted: boolean;
  reservationId: string | null;
  replay: boolean;
  code: string;
};

export async function reserveAiTestBudget(input: {
  supabaseUrl: string; serviceRoleKey: string; accountId: string; operationId: string;
  kind: 'LLM' | 'STT'; signal?: AbortSignal;
}): Promise<AiTestBudgetResult> {
  const abort = new AbortController();
  const stop = () => abort.abort();
  const timeout = setTimeout(stop, 5000);
  input.signal?.addEventListener('abort', stop, { once: true });
  if (input.signal?.aborted) stop();
  const assertActive = () => {
    if (abort.signal.aborted) throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
  };
  try {
    assertActive();
    const response = await fetch(input.supabaseUrl + '/rest/v1/rpc/rpc_ai_test_budget_reserve_service', {
      method: 'POST', redirect: 'error', signal: abort.signal,
      headers: { 'Content-Type': 'application/json', apikey: input.serviceRoleKey, Authorization: 'Bearer ' + input.serviceRoleKey },
      body: JSON.stringify({ p_account_id: input.accountId, p_operation_id: input.operationId, p_kind: input.kind,
        p_max_cost_microusd: input.kind === 'LLM' ? AI_TEST_LIMITS.llmReservationMicrousd : AI_TEST_LIMITS.speechReservationMicrousd }),
    });
    if (abort.signal.aborted || !response.ok || !response.body) { void response.body?.cancel(); throw new Error('AI_TEST_BUDGET_UNAVAILABLE'); }
    const reader = response.body.getReader();
    let content = '', length = 0;
    try {
      const decoder = new TextDecoder();
      while (true) {
        const part = await reader.read();
        assertActive();
        if (part.done) break;
        length += part.value.byteLength;
        if (length > 4096) throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
        content += decoder.decode(part.value, { stream: true });
      }
      content += decoder.decode();
    } finally { void reader.cancel().catch(() => undefined); }
    const result = JSON.parse(content);
    const codes = ['AI_TEST_RESERVED','AI_TEST_OPERATION_REPLAY','AI_TEST_BUDGET_NOT_READY','AI_TEST_ACCOUNT_NOT_ADMITTED','AI_TEST_BUDGET_EXHAUSTED'];
    if (!result || Object.keys(result).length !== 4 || typeof result.admitted !== 'boolean' || typeof result.replay !== 'boolean'
      || !codes.includes(result.code) || !(result.reservationId === null || /^[0-9a-f-]{36}$/i.test(result.reservationId))
      || (result.admitted && (result.replay || result.code !== 'AI_TEST_RESERVED' || !result.reservationId))) {
      throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
    }
    assertActive();
    return result;
  } finally { clearTimeout(timeout); input.signal?.removeEventListener('abort', stop); stop(); }
}

/** A session that produced nothing spent nothing, so its worst-case hold goes back.
 *  The RPC itself refuses to release any operation that has recorded usage. */
export async function releaseUnusedAiTestReservation(input: {
  supabaseUrl: string; serviceRoleKey: string; operationId: string;
}): Promise<boolean> {
  const abort = new AbortController();
  const timeout = setTimeout(() => abort.abort(), 5000);
  try {
    const response = await fetch(input.supabaseUrl + '/rest/v1/rpc/rpc_ai_test_release_unused_reservation_service', {
      method: 'POST', redirect: 'error', signal: abort.signal,
      headers: { 'Content-Type': 'application/json', apikey: input.serviceRoleKey, Authorization: 'Bearer ' + input.serviceRoleKey },
      body: JSON.stringify({ p_operation_id: input.operationId }),
    });
    if (!response.ok) { void response.body?.cancel(); return false; }
    const body = await response.json().catch(() => null);
    return !!body && body.released === true;
  } catch { return false; }
  finally { clearTimeout(timeout); }
}

/** A session that did transcribe settles against the audio it actually sent, priced at the
 *  published rate. The RPC refuses when provider usage exists, so reported usage always wins. */
export async function settleAiTestAudio(input: {
  supabaseUrl: string; serviceRoleKey: string; operationId: string; audioBytes: number; transcriptChars: number;
}): Promise<boolean> {
  if (!(input.audioBytes > 0)) return false;
  const abort = new AbortController();
  const timeout = setTimeout(() => abort.abort(), 5000);
  try {
    const response = await fetch(input.supabaseUrl + '/rest/v1/rpc/rpc_ai_test_settle_audio_service', {
      method: 'POST', redirect: 'error', signal: abort.signal,
      headers: { 'Content-Type': 'application/json', apikey: input.serviceRoleKey, Authorization: 'Bearer ' + input.serviceRoleKey },
      body: JSON.stringify({ p_operation_id: input.operationId, p_audio_bytes: input.audioBytes, p_transcript_chars: input.transcriptChars }),
    });
    if (!response.ok) { void response.body?.cancel(); return false; }
    const body = await response.json().catch(() => null);
    return !!body && body.settled === true;
  } catch { return false; }
  finally { clearTimeout(timeout); }
}

// @ts-nocheck
// Native authenticated bounded audio proxy. Provider key never leaves this Edge boundary.
import { releaseUnusedAiTestReservation, reserveAiTestBudget, settleAiTestAudio } from '../_shared/aiTestBudget.ts';
import { bridgeSpeech } from './proxy.ts';

const uuid = (value: unknown) => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
const deny = (status: number, code: string) => new Response(JSON.stringify({ code }), {
  status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
});

async function readBounded(url: string, headers: Record<string,string>, signal: AbortSignal, maxBytes: number, body?: unknown) {
  const controller = new AbortController();
  const stop = () => controller.abort();
  const timer = setTimeout(stop, 5000);
  signal.addEventListener('abort', stop, { once: true });
  if (signal.aborted) stop();
  const assertActive = () => { if (controller.signal.aborted) throw new Error('SPEECH_NOT_READY'); };
  try {
    assertActive();
    const response = await fetch(url, { headers, signal: controller.signal, redirect: 'error',
      method: body === undefined ? 'GET' : 'POST', body: body === undefined ? undefined : JSON.stringify(body) });
    if (controller.signal.aborted || !response.ok || !response.body) { void response.body?.cancel(); throw new Error('SPEECH_NOT_READY'); }
    const reader = response.body.getReader();
    let bytes = 0, text = '';
    const decoder = new TextDecoder();
    try {
      while (true) {
        const part = await reader.read(); assertActive(); if (part.done) break;
        bytes += part.value.byteLength;
        if (bytes > maxBytes) throw new Error('SPEECH_NOT_READY');
        text += decoder.decode(part.value, { stream: true });
      }
      text += decoder.decode(); assertActive(); return JSON.parse(text);
    } finally { void reader.cancel().catch(() => undefined); }
  } finally { clearTimeout(timer); signal.removeEventListener('abort', stop); stop(); }
}

Deno.serve(async (req: Request) => {
  if (req.method !== 'GET' || req.headers.get('upgrade')?.toLowerCase() !== 'websocket') return deny(405, 'SPEECH_WEBSOCKET_REQUIRED');
  const authorization = req.headers.get('Authorization') ?? '';
  if (!/^Bearer [^\s]+$/.test(authorization)) return deny(401, 'AUTH_REQUIRED');
  const url = new URL(req.url);
  const conversationId = url.searchParams.get('conversationId')?.toLowerCase();
  const operationId = url.searchParams.get('operationId')?.toLowerCase();
  if ([...url.searchParams.keys()].length !== 2 || !uuid(conversationId) || !uuid(operationId)) return deny(400, 'SPEECH_REQUEST_INVALID');
  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY') ?? '';
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  const providerKey = Deno.env.get('GEMINI_API_KEY') ?? '';
  // Named operator acknowledgement of the approved paid service; no free-tier/personal-data assumption.
  // Owner-approved controlled short probes with an internal reservation budget.
  // An operator verifies actual spend after each probe; this is not a provider billing guarantee.
  if (!supabaseUrl || !anonKey || !serviceRoleKey || !providerKey || Deno.env.get('USKOCI_GEMINI_PAID_TEST_ENABLED') !== 'true'
    || Deno.env.get('USKOCI_SPEECH_CONTROLLED_TEST_ENABLED') !== 'true') {
    return deny(503, 'SPEECH_NOT_READY');
  }
  try {
    const headers = { apikey: anonKey, Authorization: authorization };
    const account = await readBounded(supabaseUrl + '/auth/v1/user', headers, req.signal, 65536);
    if (!uuid(account?.id)) return deny(401, 'AUTH_REQUIRED');
    const conversations = await readBounded(supabaseUrl + '/rest/v1/ai_conversations?id=eq.' + conversationId
      + '&select=id,account_id,status,purpose&limit=1', headers, req.signal, 4096);
    const conversation = Array.isArray(conversations) && conversations.length === 1 ? conversations[0] : null;
    if (!conversation || conversation.id !== conversationId || conversation.account_id !== account.id
      || conversation.status !== 'OPEN' || !['NEED_INTAKE','PROFILE'].includes(conversation.purpose)) return deny(404, 'CONVERSATION_NOT_FOUND');
    if (conversation.purpose === 'PROFILE') {
      const context = await readBounded(supabaseUrl + '/rest/v1/rpc/rpc_read_worker_ai_context_service',
        { apikey: serviceRoleKey, Authorization: 'Bearer ' + serviceRoleKey, 'Content-Type': 'application/json' }, req.signal, 524288,
        { p_account_id: account.id, p_conversation_id: conversationId });
      if (context?.schemaVersion !== 'WORKER_PROFILE_V1' || context.accountId !== account.id || context.conversationId !== conversationId
        || context.status !== 'OPEN' || context.stale !== false || !['ALLOW','CLARIFY'].includes(context.safety)) {
        return deny(409, 'WORKER_AI_NOT_EDITABLE');
      }
    }
    const budget = await reserveAiTestBudget({ supabaseUrl, serviceRoleKey, accountId: account.id, operationId, kind: 'STT', signal: req.signal });
    if (!budget.admitted || budget.replay) return deny(409, budget.code);
    if (req.signal.aborted) return deny(409, 'SPEECH_CANCELLED');
    const { socket, response } = Deno.upgradeWebSocket(req, { idleTimeout: 30 });
    // Browser/native peer sends only our allowlisted audio protocol; it never controls this URL or setup.
    const upstream = new WebSocket('wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContent?key=' + encodeURIComponent(providerKey));
    bridgeSpeech(socket, upstream, conversationId, operationId, (transcribed, audioBytes, transcriptChars) => {
      // Nothing transcribed means nothing was charged, so the worst-case hold goes back.
      // A session that did transcribe settles against the audio it actually sent, because
      // the provider reports no usage on this stream. If that settlement cannot run, the
      // full hold stays, which overstates cost rather than understating it.
      EdgeRuntime.waitUntil(transcribed
        ? settleAiTestAudio({ supabaseUrl, serviceRoleKey, operationId, audioBytes, transcriptChars })
        : releaseUnusedAiTestReservation({ supabaseUrl, serviceRoleKey, operationId }));
    });
    // The HTTP request ends at upgrade, while the bounded socket session remains active.
    // Hold the worker until the actual close event, including delivery of its final frame.
    const closed = new Promise<void>(resolve => {
      const onClose = socket.onclose;
      socket.onclose = event => { try { onClose?.call(socket, event); } finally { resolve(); } };
    });
    if (typeof EdgeRuntime !== 'undefined') EdgeRuntime.waitUntil(closed);
    return response;
  } catch { return deny(503, 'SPEECH_UNAVAILABLE'); }
});

import { SPEECH_LIMITS, SPEECH_MODEL, SPEECH_PROTOCOL, pcmBase64Bytes } from '../../../src/features/voice/speechProtocol.ts';
import { AI_TEST_LIMITS } from '../_shared/aiTestBudget.ts';

type Socket = Pick<WebSocket, 'readyState' | 'bufferedAmount' | 'send' | 'close' | 'onopen' | 'onmessage' | 'onerror' | 'onclose'>;
const object = (v: unknown): v is Record<string, any> => !!v && typeof v === 'object' && !Array.isArray(v);
const safeText = (v: unknown): v is string => typeof v === 'string' && v.length <= SPEECH_LIMITS.transcriptCharacters
  && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(v);

/** All audio remains in bounded memory. The client cannot choose model, tools, VAD or pricing bounds. */
export function bridgeSpeech(client: Socket, upstream: Socket, conversationId: string, operationId: string,
  onFinished?: (transcribed: boolean, audioBytes: number, transcriptChars: number) => void) {
  let transcribedAnything = false;
  let ended = false, ready = false, providerSetup = false, released = false, eventSequence = 0, audioSequence = 0;
  let audioBytes = 0, segmentIndex = 0, finalText = '', interimText = '', turnComplete = false;
  let receivedProviderBytes = 0;
  let deadline: ReturnType<typeof setTimeout>;
  const send = (event: Record<string, unknown>) => {
    if (ended || client.readyState !== 1 || client.bufferedAmount > SPEECH_LIMITS.outgoingBufferBytes) return false;
    try { client.send(JSON.stringify({ protocol: SPEECH_PROTOCOL, conversationId, operationId, sequence: eventSequence++, ...event })); return true; }
    catch { return false; }
  };
  const close = () => {
    if (ended) return;
    ended = true; clearTimeout(deadline);
    // Reported before the buffers are cleared, so the caller can settle a session that
    // never transcribed anything and therefore cost nothing.
    // audioBytes counts exactly what was forwarded to the provider, which is what the
    // provider bills for; the transcript size bounds the output side.
    try { onFinished?.(transcribedAnything, audioBytes, finalText.length); } catch { }
    finalText = ''; interimText = '';
    try { upstream.close(1000, 'session ended'); } catch { }
    try { client.close(1000, 'session ended'); } catch { }
  };
  const error = (code: string) => { send({ kind: 'error', code }); close(); };
  const timeout = (ms: number) => { clearTimeout(deadline); deadline = setTimeout(() => error('SPEECH_TIMEOUT'), ms); };
  const complete = () => {
    if (!released || !turnComplete || interimText || !finalText.trim()) return;
    send({ kind: 'final', text: finalText.trim() }); close();
  };
  const beginInput = () => {
    if (ended || ready || !providerSetup || client.readyState !== 1) return;
    ready = true;
    upstream.send(JSON.stringify({ realtimeInput: { activityStart: {} } }));
    if (!send({ kind: 'ready' })) { close(); return; }
    timeout(SPEECH_LIMITS.captureMs);
  };
  timeout(SPEECH_LIMITS.setupMs);
  client.onopen = beginInput;

  upstream.onopen = () => {
    if (ended) { try { upstream.close(); } catch { } return; }
    upstream.send(JSON.stringify({ setup: { model: 'models/' + SPEECH_MODEL,
      generationConfig: { responseModalities: ['TEXT'], maxOutputTokens: AI_TEST_LIMITS.speechMaxOutputTokens, candidateCount: 1 },
      realtimeInputConfig: { automaticActivityDetection: { disabled: true }, activityHandling: 'NO_INTERRUPTION' },
      inputAudioTranscription: { languageCodes: ['sr-RS'], mode: 'VERBATIM' },
    } }));
  };
  // The provider delivers its JSON frames as binary, so a string-only reader rejects even
  // `{"setupComplete": {}}`. Decoding is async for a Blob, and transcript order matters,
  // so frames are processed one at a time through this chain.
  let frames: Promise<void> = Promise.resolve();
  const frameText = async (data: unknown): Promise<string | null> => {
    if (typeof data === 'string') return data.length > 32768 ? null : data;
    if (data instanceof Blob) return data.size > 32768 ? null : await data.text();
    if (data instanceof ArrayBuffer) return data.byteLength > 32768 ? null : new TextDecoder().decode(data);
    if (ArrayBuffer.isView(data)) {
      const view = data as ArrayBufferView;
      return view.byteLength > 32768 ? null : new TextDecoder().decode(view.buffer.slice(view.byteOffset, view.byteOffset + view.byteLength));
    }
    return null;
  };
  // A string frame is handled synchronously exactly as before. Only a binary frame needs
  // decoding, and while one is in flight later frames queue behind it so transcript order
  // is never disturbed.
  let decoding = 0;
  upstream.onmessage = event => {
    if (ended) return;
    if (typeof event.data === 'string' && decoding === 0) { handleText(event.data); return; }
    decoding += 1;
    frames = frames
      .then(async () => { const raw = await frameText(event.data); if (raw === null) { error('SPEECH_INVALID'); return; } handleText(raw); })
      .catch(() => { error('SPEECH_INVALID'); })
      .finally(() => { decoding -= 1; });
  };
  const handleText = (raw: string) => {
    if (ended) return;
    if (raw.length > 32768) { error('SPEECH_INVALID'); return; }
    receivedProviderBytes += new TextEncoder().encode(raw).byteLength;
    if (receivedProviderBytes > 1048576) { error('SPEECH_LIMIT'); return; }
    let message: Record<string, any>;
    try { message = JSON.parse(raw); } catch { error('SPEECH_INVALID'); return; }
    if (!object(message)) { error('SPEECH_INVALID'); return; }
    if (message.error || message.toolCall || message.goAway || message.sessionResumptionUpdate) { error('SPEECH_UNAVAILABLE'); return; }
    if (message.setupComplete) {
      if (providerSetup) { error('SPEECH_INVALID'); return; }
      providerSetup = true;
      beginInput();
    }
    const content = message.serverContent;
    if (content !== undefined && !object(content)) { error('SPEECH_INVALID'); return; }
    if (!content) return;
    if (!ready || content.interrupted) { error('SPEECH_INCOMPLETE'); return; }
    if (content.interimInputTranscription) {
      const text = content.interimInputTranscription.text;
      if (!safeText(text) || finalText.length + text.length > SPEECH_LIMITS.transcriptCharacters) { error('SPEECH_LIMIT'); return; }
      interimText = text;
      if (!send({ kind: 'segment', index: segmentIndex, final: false, text })) { close(); return; }
    }
    if (content.inputTranscription) {
      const text = content.inputTranscription.text;
      if (!safeText(text) || finalText.length + text.length > SPEECH_LIMITS.transcriptCharacters) { error('SPEECH_LIMIT'); return; }
      // Provider final chunks are ordered by this WebSocket; do not deduplicate repeated spoken words by value.
      finalText += text;
      if (text.trim()) transcribedAnything = true;
      interimText = '';
      if (!send({ kind: 'segment', index: segmentIndex++, final: true, text })) { close(); return; }
    }
    if (content.turnComplete === true) {
      // A provider pause is never permission to submit while the gesture remains held.
      if (!released) { error('SPEECH_INCOMPLETE'); return; }
      turnComplete = true;
    }
    // Proven by a controlled probe on 2026-09-17: gemini-3.5-transcribe-live never sends
    // turnComplete. After activityEnd it sends inputTranscription and then
    // generationComplete: true, 306 ms later, and nothing else for 20 s. Waiting only for
    // turnComplete is why every session ended in FINALIZATION_TIMEOUT with a perfect
    // transcript already in hand. generationComplete counts only after release, so it can
    // never finish a gesture that is still held.
    if (content.generationComplete === true && released) turnComplete = true;
    complete();
  };
  client.onmessage = event => {
    if (ended) return;
    if (typeof event.data !== 'string' || event.data.length > 4800) { error('SPEECH_INVALID'); return; }
    let message: Record<string, any>;
    try { message = JSON.parse(event.data); } catch { error('SPEECH_INVALID'); return; }
    if (!object(message)) { error('SPEECH_INVALID'); return; }
    if (message.kind === 'cancel' && Object.keys(message).length === 1) { close(); return; }
    if (!ready || released || upstream.readyState !== 1) { error('SPEECH_INVALID'); return; }
    if (message.kind === 'release' && Object.keys(message).length === 1) {
      released = true;
      upstream.send(JSON.stringify({ realtimeInput: { activityEnd: {} } }));
      timeout(SPEECH_LIMITS.finalizationMs);
      return;
    }
    const bytes = pcmBase64Bytes(message.pcmBase64);
    if (message.kind !== 'audio' || Object.keys(message).length !== 3 || message.sequence !== audioSequence || bytes === null) {
      error('SPEECH_INVALID'); return;
    }
    if (audioBytes + bytes > AI_TEST_LIMITS.speechPcmBytes || upstream.bufferedAmount > SPEECH_LIMITS.outgoingBufferBytes) {
      error('SPEECH_LIMIT'); return;
    }
    audioBytes += bytes; audioSequence++;
    upstream.send(JSON.stringify({ realtimeInput: { audio: { data: message.pcmBase64, mimeType: 'audio/pcm;rate=16000' } } }));
    message.pcmBase64 = ''; // Do not retain audio in session state, storage or logs.
  };
  client.onerror = close;
  client.onclose = close;
  upstream.onerror = () => error('SPEECH_UNAVAILABLE');
  upstream.onclose = () => { if (!ended) error('SPEECH_INCOMPLETE'); };
  return close;
}
